'use strict'
const fs=require('node:fs')
const assert=require('node:assert/strict')
const read=p=>fs.readFileSync(p,'utf8')
const registry=read('lib/permissoesBlocos.ts')
const materials=read('app/api/vendas/tipologias-materiais/route.ts')
const approval=read('app/api/vendas/wvetro/conferencia-documental/route.ts')
const ui=read('components/clientes/VendaTipologiasMateriais.tsx')
for(const action of ['clientes.portal.tipologias_substituir','clientes.portal.tipologias_aprovar']){
 assert.ok(registry.includes(" '"+action+"',"),'Ação protegida não está na lista de delegações explícitas: '+action)
 assert.ok(registry.includes("a('"+action+"'"),'Ação não cadastrada nas permissões: '+action)
 assert.ok(materials.includes("acaoId:'"+action+"'")||approval.includes("acaoId:'"+action+"'"))
}
assert.match(materials,/if\(modo==='permissoes'\)/)
assert.match(materials,/if\(b\.acao!=='substituir'\)return erro/)
assert.match(materials,/if\(!original\|\|!\['perfil','contramarco'\]\.includes\(original\.categoria\)\)/)
assert.match(materials,/if\(!substituto\|\|!\['perfil','contramarco'\]\.includes\(substituto\.categoria\)\|\|!substituto\.foto_url\)/)
assert.match(approval,/if\(acao!=='validar_atlas'\|\|tipo!=='tipologia'\)/)
assert.match(ui,/modo=permissoes/)
assert.match(ui,/const podeSubstituir=master\|\|permissoesTecnicas\.substituir/)
assert.match(ui,/const podeAprovar=master\|\|permissoesTecnicas\.aprovar/)
assert.match(ui,/if\(!podeSubstituir\)/)
assert.match(ui,/if\(!podeAprovar\)/)
assert.match(ui,/if\(!podeAprovar\|\|!pacoteId/)
console.log('PASS: duas delegações nominais, bloqueio por padrão, validação de tenant/categoria, aprovação de tipologia sem liberar PDF.')
